$ErrorActionPreference = 'Stop'
$m03Root = (Get-Location).Path
$m03Names = @('research','requirements','design','contracts','algorithms','validation','tasks')
$m03Files = @()
$m03Links = 0
foreach ($m03Name in $m03Names) {
  $m03Relative = "docs/design/features/m03-aeromagnetic-lines/$m03Name.md"
  $m03Body = Get-Content -LiteralPath $m03Relative -Raw -Encoding UTF8
  if ($m03Body.Length -lt 5000) { throw "Short document: $m03Name" }
  foreach ($m03Match in [regex]::Matches($m03Body,'\[[^\]]+\]\(([^)]+)\)')) {
    $m03Target = $m03Match.Groups[1].Value
    if ($m03Target -notmatch '^https?://') {
      $m03LinkPath = Join-Path (Split-Path -Parent $m03Relative) ($m03Target.Split('#')[0])
      if (-not (Test-Path -LiteralPath $m03LinkPath)) { throw "Missing relative link: $m03Relative -> $m03Target" }
      $m03Links++
    }
  }
  $m03Files += [ordered]@{path=$m03Relative;bytes=(Get-Item -LiteralPath $m03Relative).Length;sha256=(Get-FileHash -LiteralPath $m03Relative -Algorithm SHA256).Hash.ToLowerInvariant()}
}
$m03RequirementText = Get-Content -LiteralPath 'docs/design/features/m03-aeromagnetic-lines/requirements.md' -Raw -Encoding UTF8
$m03Requirements = [regex]::Matches($m03RequirementText,'(?m)^(M03-\d{3}) (WHEN|IF|WHILE) [^\r\n]*SHALL[^\r\n]*\r?\nImplementation: ([^\r\n]+)\r?\nGate: ([^\r\n]+)')
if ($m03Requirements.Count -ne 26) { throw 'EARS/path/gate count is not26' }
for ($m03Index=0;$m03Index -lt 26;$m03Index++) {
 if ($m03Requirements[$m03Index].Groups[1].Value -ne ('M03-{0:d3}' -f ($m03Index+1))) { throw 'Requirement sequence drift' }
}
$m03ContractText = Get-Content -LiteralPath 'docs/design/features/m03-aeromagnetic-lines/contracts.md' -Raw -Encoding UTF8
$m03Objects = [regex]::Matches($m03ContractText,'(?m)^\| ([A-Za-z][A-Za-z0-9]*) \| [^\r\n]*:.* \|$')
$m03Seen = @{}
$m03Fields = 0
foreach ($m03Object in $m03Objects) {
 $m03ObjectName = $m03Object.Groups[1].Value
 if ($m03ObjectName -eq 'Object') { continue }
 if ($m03Seen.ContainsKey($m03ObjectName)) { throw "Duplicate object table: $m03ObjectName" }
 $m03Seen[$m03ObjectName]=$true
 $m03KeyMatches = [regex]::Matches($m03Object.Value,'(?:\| |; )([a-z][a-z0-9_]*):')
 $m03Keys = @($m03KeyMatches | ForEach-Object { $_.Groups[1].Value })
 if (($m03Keys | Select-Object -Unique).Count -ne $m03Keys.Count) { throw "Duplicate typed key: $m03ObjectName" }
 $m03Fields += $m03Keys.Count
}
$m03PrimaryPath = 'docs/research/m03-primary-retrieval-2026-10-03.json'
$m03Primary = Get-Content -LiteralPath $m03PrimaryPath -Raw -Encoding UTF8 | ConvertFrom-Json
foreach ($m03Receipt in $m03Primary.receipts) {
 if ((Get-Item -LiteralPath $m03Receipt.cache_path).Length -ne $m03Receipt.bytes) { throw "Body size drift: $($m03Receipt.id)" }
 if ((Get-FileHash -LiteralPath $m03Receipt.cache_path -Algorithm SHA256).Hash.ToLowerInvariant() -ne $m03Receipt.sha256) { throw "Body hash drift: $($m03Receipt.id)" }
}
$m03Files += [ordered]@{path=$m03PrimaryPath;bytes=(Get-Item -LiteralPath $m03PrimaryPath).Length;sha256=(Get-FileHash -LiteralPath $m03PrimaryPath -Algorithm SHA256).Hash.ToLowerInvariant()}
[ordered]@{meaning='Documentation shape/link/custody only, not implementation/science acceptance';seven_files=7;ears_requirements=26;relative_links=$m03Links;named_typed_objects=$m03Seen.Count;typed_keys=$m03Fields;response_body_hashes=$m03Primary.receipts.Count;http200=@($m03Primary.receipts | Where-Object http_status -eq '200').Count;http403=@($m03Primary.receipts | Where-Object http_status -eq '403').Count;files=$m03Files} | ConvertTo-Json -Depth 12

import hashlib,json,math
rows=[]
north=[-1400,-950,-520,-170,230,610,1050,1500]
east=[-1100,0,1000]
for li in range(11):
    line=('F%02d'%li) if li<8 else ('T%02d'%(li-8))
    for j in range(33):
        rid=line+'.%03d'%j
        e=(-1600+100*j if li%2==0 else 1600-100*j) if li<8 else east[li-8]
        n=north[li] if li<8 else -1600+100*j
        def jitter(axis):
            return 0.0 if j in (0,32) else (int.from_bytes(hashlib.sha256(('m03/20261003/'+rid+'/'+axis).encode('ascii')).digest()[:2],'big')%1001-500)/100
        rows.append(dict(id=rid,line=line,ordinal=j,e=float(e)+jitter('e'),n=float(n)+jitter('n')))
byline={line:[r for r in rows if r['line']==line] for line in sorted({r['line'] for r in rows})}
def intersects(p,q,b):
    lo,hi=0.0,1.0
    dx,dy=q['e']-p['e'],q['n']-p['n']
    for a,c in ((-dx,p['e']-b[0]),(dx,b[1]-p['e']),(-dy,p['n']-b[2]),(dy,b[3]-p['n'])):
        if a==0:
            if c<0:return False
        else:
            z=c/a
            if a<0:lo=max(lo,z)
            else:hi=min(hi,z)
            if lo>hi:return False
    return True
outer=(-1610,1610,215,245)
folds=[('A',['F01','F06'],[(-1610,1610,-965,-935),(-1610,1610,1035,1065)],168,66),('B',['F02','F05'],[(-1610,1610,-535,-505),(-1610,1610,595,625)],195,66),('C',['F03'],[(-1610,1610,-185,-155)],249,33)]
def inventory(val,blocks):
    expanded=[(b[0]-470,b[1]+470,b[2]-470,b[3]+470) for b in blocks]
    denied=set()
    for line,rr in byline.items():
        if line.startswith('T'):
            for p,q in zip(rr,rr[1:]):
                if any(intersects(p,q,b) for b in expanded):denied.update((p['id'],q['id']))
    training=[r for r in rows if r['line'] not in set(val+['F04']) and r['id'] not in denied]
    validation=[r for r in rows if r['line'] in val]
    nearest=max(min(math.hypot(r['e']-t['e'],r['n']-t['n']) for t in training) for r in validation)
    assert nearest<470
    assert all(-1600<=r['e']<=1600 and -1400<=r['n']<=1500 for r in validation)
    blocks_map={}
    for r in sorted(training,key=lambda r:r['id']):
        key=(math.floor((r['e']+1600)/400),math.floor((r['n']+1600)/400))
        blocks_map.setdefault(key,[]).append(r)
    centers=[dict(block=list(k),count=len(v),e=math.fsum(x['e'] for x in v)/len(v),n=math.fsum(x['n'] for x in v)/len(v)) for k,v in sorted(blocks_map.items())]
    assert len(centers)<=256
    assert sum(x['count'] for x in centers)==len(training)
    for x in (-2000,-1600,-1200,1600):
        assert math.floor((x+1600)/400) in (-1,0,1,8)
    return dict(training=len(training),validation=len(validation),masked_tie_rows=len(denied),source_blocks=len(centers),max_nearest_m=nearest,geometry_only_supported=len(validation))
result={'notice':'Documentation geometry arithmetic only: no magnetic values, engine fit, IGRF, provider measurements or field acceptance.','rows':len(rows),'original_segments':sum(len(v)-1 for v in byline.values()),'outer':inventory(['F04'],[outer]),'inner':{}}
assert result['outer']['training']==294 and result['outer']['validation']==33
for name,ids,blocks,train_count,val_count in folds:
    item=inventory(ids,[outer]+blocks)
    assert item['training']==train_count and item['validation']==val_count
    result['inner'][name]=item
result['geometry_preview_sha256']=hashlib.sha256(json.dumps(rows,sort_keys=True,ensure_ascii=False,separators=(',',':'),allow_nan=False).encode('utf-8')).hexdigest()
print(json.dumps(result,sort_keys=True))
